# The OAuth token endpoint (generated by maquina:oauth): exchanges a code,
# or rotates a refresh token. Public clients only, so PKCE stands in for a
# client secret. Errors are RFC 6749 JSON; raw values never reach a log.
class Oauth::TokensController < ActionController::API
  before_action :no_store

  # POST /oauth/token
  def create
    case params[:grant_type]
    when "authorization_code" then exchange_code
    when "refresh_token" then refresh
    when nil, "" then render_error "invalid_request", "grant_type is required"
    else render_error "unsupported_grant_type", "grant_type must be authorization_code or refresh_token"
    end
  end

  private

  def exchange_code
    return render_error("invalid_request", "code, redirect_uri, client_id and code_verifier are required") if
      params.values_at(:code, :redirect_uri, :client_id, :code_verifier).any?(&:blank?)
    return render_error("invalid_target", "resource must be #{mcp_resource}") unless params[:resource] == mcp_resource

    client = OauthClient.find_by(client_id: params[:client_id]) or return invalid_grant
    code = OauthAuthorizationCode.redeem!(params[:code], client: client, redirect_uri: params[:redirect_uri],
      verifier: params[:code_verifier])
    return render_error("invalid_target", "resource does not match the authorization") unless code.resource == params[:resource]

    access_token, refresh_token = AccessToken.issue!(user: code.user, client: client, scope: code.scope, resource: code.resource)
    Rails.logger.info "[OAUTH] Token issued to #{client.client_id} for #{code.user.email_address} (#{code.scope})"
    render_token access_token, refresh_token, code.scope
  rescue OauthAuthorizationCode::InvalidGrant
    invalid_grant
  end

  def refresh
    return render_error("invalid_request", "refresh_token and client_id are required") if
      params.values_at(:refresh_token, :client_id).any?(&:blank?)

    client = OauthClient.find_by(client_id: params[:client_id]) or return invalid_grant
    token = AccessToken.find_by_refresh_token(params[:refresh_token]) or return invalid_grant
    return render_error("invalid_target", "resource does not match the grant") if params[:resource].present? && params[:resource] != token.resource

    access_token, refresh_token = token.rotate!(client: client)
    Rails.logger.info "[OAUTH] Token refreshed for #{client.client_id} (#{token.user.email_address})"
    render_token access_token, refresh_token, token.scope
  rescue AccessToken::InvalidGrant
    invalid_grant
  end

  def mcp_resource
    "#{request.base_url}/mcp"
  end

  def render_token(access_token, refresh_token, scope)
    render json: {access_token: access_token, token_type: "Bearer", expires_in: AccessToken::ACCESS_TTL.to_i,
                  refresh_token: refresh_token, scope: scope}
  end

  def invalid_grant
    render_error "invalid_grant", "The grant is invalid, expired, already used or issued to another client"
  end

  def render_error(error, description)
    render json: {error: error, error_description: description}, status: :bad_request
  end
end
